{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In humans, 68Ga-PSMA-11 (947 Da) showed no brain uptake, attributed to its molar mass exceeding the 400–500 Da blood-brain barrier limit; the query is a much larger glycopeptide, so this high-transfer evidence supports inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In rhesus monkeys, the polar glycosylated nucleoside GAZT had a CSF/plasma ratio of only 0.04 at 1 h, 10-fold lower than AZT and AMT, demonstrating poor BBB crossing for a glycosylated, polar molecule; this transfers to the query's heavily glycosylated, polar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A sulfonated adenosine derivative was undetectable in mouse brain (<0.1% of plasma level) despite measurable plasma exposure, showing that polar, high-MW/charged molecules can be essentially excluded from the CNS; the query has multiple ionizable and polar groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Epimedin B, a glycosylated polyphenol, was the least concentrated compound in rat brain and could hardly pass the blood-brain barrier; the query shares multiple sugar and phenolic moieties, supporting poor CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Ginsenoside Rg1, a large glycosylated natural product, showed poor brain tissue distribution (14.59 ng/mL) in rats, consistent with the query's large glycosylated structure being unable to achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, heavily glycosylated glycopeptide with multiple ionizable groups and a molecular mass far above the usual BBB threshold; all transferable experimental evidence from glycosylated, polar, and high-molecular-weight molecules shows poor brain penetration, so meaningful CNS access is predicted to be inadequate.",
  "evidence_gaps": [
    "No direct brain, CSF, or microdialysis measurement exists for the exact query molecule.",
    "No data on the effect of possible active efflux transporters or disease-state BBB disruption are available for the query.",
    "Transfer relies on structurally related glycosylated/polar large molecules rather than query-specific pharmacokinetic data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

